"""Explain page chunks and report-run transitions with byte examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1733': ('공책 여러 쪽에 걸친 줄을 읽을 때 한 쪽 끝까지만 먼저 읽고 다음 쪽으로 넘어가요. 읽을 양이 남았어도 현재 쪽 경계를 한 번에 넘어가지 않아요.', '남은 요청 길이와 페이지 잔여 길이 중 작은 값으로 검사 단위를 정합니다.', '페이지 크기4096,시작4092,길이12를 놓고 첫4바이트·다음8바이트와 pos0→4→12를 적으세요.', ['kmsan_internal_check_memory는 메모리 범위의 준비 상태를 검사해요. shadow는 각 데이터 바이트가 준비됐는지 추적하는 정보예요. 실제 데이터 숫자가0인지 확인하는 함수와는 달라요.', '페이지는 메모리를 일정한 크기로 나눈 덩어리예요. 이 함수는 요청 범위를 페이지 경계에서 chunk로 나눠요. chunk는 이번에 처리할 조각이라는 뜻이에요. 각 조각의 shadow를 찾아 그 안을 읽어요.', 'pos는 요청 시작부터 이미 얼마나 진행했는지 나타내요. size-pos는 아직 남은 길이예요. 현재 주소 addr64+pos를 페이지 크기로 나눈 나머지는 페이지 안의 위치이고, 페이지 크기에서 그 위치를 빼면 이번 페이지에 남은 길이가 돼요.', 'chunk_size는 두 남은 길이 중 작은 값이에요. 페이지4096,시작4092,길이12이면 요청은12 남았고 페이지에는4 남아요. min(12,4)=4를 먼저 처리하고 pos를4로 옮겨요. 다음 주소4096에서는 요청이8 남으므로 다음 조각은8이에요.', '길이가0이면 맨 앞 if(!size) return에서 끝나요. 검사할 바이트가 없는데 한 페이지를 억지로 읽지 않아요. 길이가 있을 때만 연속성 조건을 확인하고 반복문에 들어가요.', '페이지별 조각과 보고 그룹은 다른 구분이에요. 조각 경계를 넘었다는 이유만으로 진행 중 원인을 지우지는 않아요. 정상적으로 추적되는 연속 범위에서 같은 원인의 미준비 바이트가 이어지면 여러 조각을 하나의 보고 그룹으로 묶을 수도 있어요.'], [('페이지 끝까지4바이트 남은 곳에서12바이트를 검사하면 첫 조각은 얼마인가요?', ['12바이트 전부예요', '4바이트예요'], '정답은 두 번째예요. 요청 잔여12와 페이지 잔여4 중 작은4를 골라요. 다음 페이지에서 나머지8을 처리하므로 전체 길이는12로 유지돼요.'), ('검사 길이0이면 shadow를 계속 읽나요?', ['아니요. 처음에 바로 돌아가요', '네. 언제나 한 페이지를 검사해요'], '정답은 첫 번째예요. if(!size) return이 있어요. 길이0은 검사할 칸이 없으므로 반복문까지 진행하지 않아요.')]), 'os1734': ('같은 색의 문제 칸이 양쪽에 있어도 가운데 정상 칸이 끼면 하나로 이어진 덩어리가 아니에요. 보고할 때 정상 칸까지 문제로 묶지 않아야 해요.', '같은 원인과 연속성 두 조건으로 보고 그룹을 구별합니다.', 'shadow [FF,FF,0,FF]와 원인77을 그리고 보고 구간0~1과3~3을 따로 색칠하세요.', ['poison은 준비되지 않았다고 표시된 상태, clean 또는 unpoisoned는 준비된 상태를 뜻해요. 여기서 shadow0은 clean이에요. 실제 데이터 값이0인지를 말하는 것이 아니라 검사 상태를 말해요.', 'run은 같은 성질이 연속해서 이어지는 구간이에요. 함수는 현재 원인 cur_origin과 그룹 시작 cur_off_start를 기억해요. origin은 문제의 출처 기록을 가리키는 번호예요. 이 예에서는 정상적인 비영 원인77을 사용해요.', '바이트를 보다가 shadow0을 만나면 앞에 진행 중인 문제 구간이 있었는지 확인해요. 있었다면 정상 칸 바로 앞까지 보고해요. 그 끝 위치는 pos+i-1이고 현재 clean 칸은 보고 범위에 넣지 않아요.', '예를 들어 offset0·1은 미준비,2는 준비됨,3은 다시 미준비이고 모두 문제 원인이77이라고 해 봐요. offset2에서 앞 구간0~1을 보고하고 끝내요. offset3은 같은 원인이어도 새 구간3~3으로 시작해요.', 'clean을 처리한 뒤 cur_origin=0,cur_off_start=-1로 바꿔 진행 중 그룹이 없음을 표시해요. 0과-1은 여기서 상태를 나타내는 값이에요. 실제 데이터나 저장된 모든 원인 기록을 지우는 작업은 아니에요.', '같은 origin이라는 조건만으로 떨어진 문제 칸을 합치면 중간 정상 칸까지 문제라고 보고하게 돼요. 같은 원인과 연속된 미준비 바이트라는 두 조건을 함께 봐야 정확한 위치를 알려 줄 수 있어요.'], [('원인77인 문제 칸0~1,정상 칸2,문제 칸3은 한 그룹인가요?', ['네. 원인이 같으면 전부 합쳐요', '아니요. 정상 칸2가 사이에 있어 두 그룹이에요'], '정답은 두 번째예요. shadow0을 만나면 기존 그룹을 보고하고 상태를 초기화해요. 따라서0~1과3~3은 원인이 같아도 따로 보고해요.'), ('정상 칸의 offset이2이면 앞 문제 그룹의 마지막 offset은 얼마인가요?', ['1이에요', '2예요'], '정답은 첫 번째예요. 현재 정상 칸의 직전인2-1=1까지 보고해요. 정상 칸2를 미준비 범위에 포함하면 안 돼요.')]), 'os1735': ('끝까지 문제 칸이 이어지면 다음 정상 칸을 기다릴 수 없어요. 읽기가 끝나는 순간 남은 묶음을 정리해야 마지막 기록이 빠지지 않아요.', '원인이 바뀔 때와 범위가 끝날 때 보고를 마무리하는 이유를 이해합니다.', '길이8에서 원인77인0~3과 원인88인4~7을 그리세요. offset4의 전환 보고와 반복문 뒤 마지막 보고를 표시하세요.', ['같이 이어진 미준비 바이트라도 원인이 달라지면 보고 그룹을 나눠요. origin은 준비되지 않은 상태의 출처를 추적하는 기록 번호예요. 현재 기억한 cur_origin과 새 바이트의 new_origin을 비교해요.', 'offset0~3의 원인이77이고 offset4~7의 원인이88인 예를 보세요. offset4에서 새 원인을 만나면 이전 그룹은4 바로 앞인3까지예요. 먼저77의0~3을 보고하고 원인88·시작4로 새 그룹을 기억해요.', 'offset7까지 읽은 뒤에는 다음 정상 칸이나 다른 원인이 없어요. 마지막 그룹을 반복문 안의 전환 조건에서만 보고한다면88의4~7을 놓칠 수 있어요. 그래서 반복문 뒤에도 cur_origin이 남았는지 확인해요.', '검사가 끝나면 pos는 처리한 전체 길이예요. 길이8이면 pos=8이어서 마지막 포함 offset은pos-1=7이에요. 남아 있는 그룹4~7을 보고하는 마무리를 flush라고 부르기도 해요. 여기서는 CPU 캐시를 비우는 뜻이 아니라 모아 둔 보고를 마치는 뜻이에요.', '각 보고 호출 앞에는 enter_runtime,뒤에는 leave_runtime이 있어요. 보고 과정이 다시 계측 코드를 불러 재귀적으로 검사에 들어가는 일을 피하기 위한 짝이에요. 일반적인 잠금 획득이나 실제 대상 데이터 보호와 같은 뜻은 아니에요.', 'cur_origin0은 이 코드에서 현재 보고할 그룹 없음의 표시예요. 따라서 모든 임의의0 원인도 정상적으로 보고한다고 가정할 수는 없어요. 미준비 바이트의 정상 원인 기록 조건과 기록 저장 실패 처리도 함께 봐야 해요.'], [('offset4에서 원인이77에서88로 바뀌면 이전 그룹은 어디까지인가요?', ['4까지예요', '3까지예요'], '정답은 두 번째예요. 4번 칸은 새 원인의 첫 칸이에요. 이전 보고의 끝은현재 위치-1=3이고 새 시작은4예요.'), ('마지막 문제 구간 뒤에 정상 칸이 없어도 보고할 수 있나요?', ['네. 반복문이 끝난 뒤 남은 그룹을 보고해요', '아니요. 마지막 그룹은 항상 버려요'], '정답은 첫 번째예요. 마지막 if(cur_origin)에서 pos-1까지 보고해요. 다음 전환을 만나지 못한 마지막 그룹도 빠뜨리지 않으려는 처리예요.')]), 'os1736': ('읽을 수 없는 검사표 구간이 나오면 앞에서 확인한 문제까지만 말할 수 있어요. 보지 못한 칸을 모두 문제라고 하거나 모두 정상이라고 단정하면 안 돼요.', '미추적 조각에서 기존 보고를 마치고 관찰 범위를 구별합니다.', '앞4바이트는 원인77의 미준비,뒤8바이트는 shadow없음으로 그리세요. 보고는offset0~3만 포함한다고 적으세요.', ['미추적은 KMSAN이 그 범위의 검사 정보를 갖고 있지 않은 상황을 뜻해요. 페이지 조각의 shadow를 조회했는데 없으면 이 함수는 그 조각의 각 바이트 상태를 읽을 수 없어요. 값이 준비됐다고 확인한 것과는 달라요.', '이 분기에 들어올 때 앞에서 이어 오던 문제 그룹 cur_origin이 있으면 먼저 보고해요. 새 조각의 시작은pos이므로 앞 그룹의 마지막 위치는pos-1이에요. 미추적 조각의 끝까지 늘려 보고하지 않아요.', '예를 들어 요청의 앞4바이트를 미준비 원인77로 관찰하고 다음8바이트 조각에는 shadow가 없다고 해 봐요. 다음 조각에 도달한 pos는4이므로 보고 끝은3이에요. 보고 범위는0~3이며 보지 못한4~11은 포함하지 않아요.', '보고 뒤 cur_origin=0,cur_off_start=-1로 진행 중 그룹을 없애요. 그 다음 pos에 chunk_size를 더하고 continue해서 다음 조각으로 가요. continue는 현재 반복의 나머지 코드를 건너뛰는 명령이에요.', '나중에 다시 같은 원인의 추적 가능한 바이트를 만나도 미추적 구간을 가로질러 이전 그룹과 합치면 안 돼요. 중간 칸을 관찰하지 못했기 때문에 연속된 문제라는 근거가 없어요. 상태를 초기화하는 이유예요.', '이 분기는 미추적 데이터 내용을 초기화하거나 실제 바이트의 준비 여부를 확인하지 않아요. 또한 앞의 메타데이터 연속성 경고 조건은 별도의 계약이에요. 추적·미추적이 섞인 그림은 분기 이해를 위한 예이며 모든 그런 입력이 정상 실행 조건이라는 증명은 아니에요.'], [('미추적 조각을 만나면 앞에서 모으던 문제 구간은 어떻게 하나요?', ['미추적 조각 끝까지 무조건 늘려요', '새 조각 직전까지 보고하고 그룹 상태를 초기화해요'], '정답은 두 번째예요. pos-1까지만 보고해 관찰하지 못한 칸은 포함하지 않아요. 이후 상태를 비워 다음 그룹과 잘못 이어지지 않게 해요.'), ('미추적 페이지를 건너뛰었다면 그 데이터가 실제로 준비됐다는 증거인가요?', ['아니요. 검사 정보가 없어 건너뛴 것이에요', '네. 모든 바이트를 확인해서 정상이라는 뜻이에요'], '정답은 첫 번째예요. shadow 조회 실패는 정상 상태를 읽은 것과 달라요. 관찰하지 못했다는 사실을 안전성 확인으로 바꿔 말하면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_429.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
